using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class ProgramReadinessReportFileStore{private readonly string _path;public ProgramReadinessReportFileStore(string path){if(string.IsNullOrWhiteSpace(path))throw new ArgumentException("A readiness report path is required.",nameof(path));_path=Path.GetFullPath(path);}public void Save(ProgramReadinessReport value){ArgumentNullException.ThrowIfNull(value);if(value.LiveAuthorityEnabled||!value.SimulationOnly)throw new InvalidOperationException("Program readiness persistence cannot grant live authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public ProgramReadinessReport Load(){var value=JsonSerializer.Deserialize<ProgramReadinessReport>(File.ReadAllText(_path))??throw new InvalidOperationException("Program readiness report JSON is invalid.");if(value.LiveAuthorityEnabled||!value.SimulationOnly)throw new InvalidOperationException("Persisted readiness report violates simulation-only authority.");return value;}}
